/**
 * 생성 파일 — 손으로 고치지 않는다. `pnpm gen:photos`(`scripts/gen-photos.ts`)가 `assets/site/photos/*.webp` 를 읽어 쓴다.
 * 출처(Unsplash License)는 `assets/site/photos/ATTRIBUTION.md`. import 는 없다(값 파일). 사진마다 폭 두 벌 이상(srcset), 좁은 것부터.
 */

export interface SitePhotoFile {
  readonly path: string;
  readonly contentType: string;
  readonly width: number;
  readonly height: number;
  readonly hash: string;
  readonly bytes: number;
  readonly base64: string;
}

